<?php
require_once __DIR__ . '/../lib.php';
require_once __DIR__ . '/../../public/db_connect.php';  header('Content-Type: application/json');  // Check if user is authorized
$u = current_user();
$role = $u['role'] ?? 'staff';
$roleKey = function_exists('role_key') ? role_key($role) : strtolower(trim((string)$role));  if (!in_array($roleKey, ['superadmin', 'admin', 'developer'])) {  echo json_encode(['success' => false, 'error' => 'Unauthorized access']);  exit;
}  $optimization_results = [  'timestamp' => date('Y-m-d H:i:s'),  'operations' => [],  'overall_status' => 'success',  'recommendations' => []
];  try {  global $pdo;  // Start optimization logging  $stmt = $pdo->prepare("  INSERT INTO system_maintenance_log (maintenance_type, description, status, performed_by)  VALUES (?, ?, ?, ?)  ");  $stmt->execute([  'optimization',  'System optimization started',  'in_progress',  $u['id']  ]);  $maintenance_id = $pdo->lastInsertId();  // 1. Database Optimization  $db_optimization = [  'name' => 'Database Optimization',  'status' => 'success',  'message' => 'Database tables optimized',  'details' => []  ];  try {  // Get all tables  $stmt = $pdo->query("SHOW TABLES");  $tables = $stmt->fetchAll(PDO::FETCH_COLUMN);  $optimized_tables = 0;  foreach ($tables as $table) {  try {  $pdo->query("OPTIMIZE TABLE `$table`");  $optimized_tables++;  } catch(Exception $e) {  // Skip tables that can't be optimized  continue;  }  }  $db_optimization['details']['tables_optimized'] = $optimized_tables;  $db_optimization['details']['total_tables'] = count($tables);  // Update table statistics  $pdo->query("ANALYZE TABLE `" . implode('`, `', $tables) . "`");  } catch(Exception $e) {  $db_optimization['status'] = 'warning';  $db_optimization['message'] = 'Partial database optimization: ' . $e->getMessage();  $optimization_results['overall_status'] = 'warning';  }  $optimization_results['operations'][] = $db_optimization;  // 2. Cache Clear  $cache_optimization = [  'name' => 'Cache Clear',  'status' => 'success',  'message' => 'System cache cleared',  'details' => []  ];  try {  // Clear PHP opcode cache if available  if (function_exists('opcache_reset')) {  opcache_reset();  $cache_optimization['details']['opcode_cache'] = 'Cleared';  }  // Clear session cache (old sessions)  $stmt = $pdo->prepare("  DELETE FROM user_sessions  WHERE created_at < DATE_SUB(NOW(), INTERVAL 7 DAY)  ");  $stmt->execute();  $cache_optimization['details']['old_sessions_cleared'] = $stmt->rowCount();  // Update cache status in configuration  $stmt = $pdo->prepare("  UPDATE system_configuration  SET config_value = 'cleared', updated_at = NOW()  WHERE config_key = 'cache_status'  ");  $stmt->execute();  $cache_optimization['details']['cache_status'] = 'Cleared';  } catch(Exception $e) {  $cache_optimization['status'] = 'warning';  $cache_optimization['message'] = 'Partial cache clear: ' . $e->getMessage();  }  $optimization_results['operations'][] = $cache_optimization;  // 3. Log Cleanup  $log_optimization = [  'name' => 'Log Cleanup',  'status' => 'success',  'message' => 'System logs cleaned up',  'details' => []  ];  try {  // Get retention period from configuration  $stmt = $pdo->prepare("SELECT config_value FROM system_configuration WHERE config_key = 'error_log_retention_days'");  $stmt->execute();  $retention_days = $stmt->fetchColumn() ?: 90;  // Clean old audit logs  $stmt = $pdo->prepare("  DELETE FROM audit_log  WHERE created_at < DATE_SUB(NOW(), INTERVAL ? DAY)  ");  $stmt->execute([$retention_days]);  $log_optimization['details']['audit_logs_cleaned'] = $stmt->rowCount();  // Clean old health metrics  $stmt = $pdo->prepare("  DELETE FROM system_health_metrics  WHERE recorded_at < DATE_SUB(NOW(), INTERVAL 30 DAY)  ");  $stmt->execute();  $log_optimization['details']['health_metrics_cleaned'] = $stmt->rowCount();  // Clean resolved alerts older than 30 days  $stmt = $pdo->prepare("  DELETE FROM system_alerts  WHERE status = 'resolved' AND resolved_at < DATE_SUB(NOW(), INTERVAL 30 DAY)  ");  $stmt->execute();  $log_optimization['details']['resolved_alerts_cleaned'] = $stmt->rowCount();  } catch(Exception $e) {  $log_optimization['status'] = 'warning';  $log_optimization['message'] = 'Partial log cleanup: ' . $e->getMessage();  }  $optimization_results['operations'][] = $log_optimization;  // 4. System Health Update  $health_optimization = [  'name' => 'Health Metrics Update',  'status' => 'success',  'message' => 'System health metrics updated',  'details' => []  ];  try {  // Update current system metrics  $metrics_to_update = [  'memory_usage' => round(memory_get_usage(true) / 1024 / 1024, 2),  'php_version' => PHP_VERSION,  'server_uptime' => '24h+', // Placeholder  'cache_status' => 'active',  'optimization_completed' => date('Y-m-d H:i:s')  ];  foreach ($metrics_to_update as $metric_name => $metric_value) {  $stmt = $pdo->prepare("  INSERT INTO system_health_metrics (metric_name, metric_value, metric_unit, status)  VALUES (?, ?, ?, 'good')  ON DUPLICATE KEY UPDATE  metric_value = VALUES(metric_value),  recorded_at = NOW()  ");  $stmt->execute([$metric_name, $metric_value, 'string']);  }  $health_optimization['details']['metrics_updated'] = count($metrics_to_update);  } catch(Exception $e) {  $health_optimization['status'] = 'warning';  $health_optimization['message'] = 'Partial health update: ' . $e->getMessage();  }  $optimization_results['operations'][] = $health_optimization;  // 5. Configuration Check  $config_optimization = [  'name' => 'Configuration Check',  'status' => 'success',  'message' => 'System configuration verified',  'details' => []  ];  try {  // Check critical configuration values  $critical_configs = [  'system_version' => '2.1.0',  'backup_retention_days' => '30',  'auto_backup_enabled' => 'true',  'cache_clear_interval_hours' => '6'  ];  $missing_configs = [];  foreach ($critical_configs as $key => $default_value) {  $stmt = $pdo->prepare("SELECT config_value FROM system_configuration WHERE config_key = ?");  $stmt->execute([$key]);  if (!$stmt->fetchColumn()) {  // Insert missing configuration  $stmt = $pdo->prepare("  INSERT INTO system_configuration (config_key, config_value, config_type, description, category)  VALUES (?, ?, 'string', ?, 'general')  ");  $stmt->execute([$key, $default_value, "Auto-generated configuration for $key"]);  $missing_configs[] = $key;  }  }  $config_optimization['details']['configs_checked'] = count($critical_configs);  $config_optimization['details']['configs_added'] = count($missing_configs);  if (!empty($missing_configs)) {  $config_optimization['message'] = 'Missing configurations added';  $optimization_results['recommendations'][] = 'Review newly added configuration values';  }  } catch(Exception $e) {  $config_optimization['status'] = 'warning';  $config_optimization['message'] = 'Configuration check incomplete: ' . $e->getMessage();  }  $optimization_results['operations'][] = $config_optimization;  // Update maintenance log  $duration = time() - strtotime($maintenance_id ? 'now' : date('Y-m-d H:i:s'));  $stmt = $pdo->prepare("  UPDATE system_maintenance_log  SET status = 'completed',  completed_at = NOW(),  duration_seconds = ?,  details = ?  WHERE id = ?  ");  $stmt->execute([  $duration,  json_encode([  'operations_completed' => count($optimization_results['operations']),  'overall_status' => $optimization_results['overall_status'],  'recommendations' => count($optimization_results['recommendations'])  ]),  $maintenance_id  ]);  // Generate recommendations  if ($optimization_results['overall_status'] === 'success') {  $optimization_results['recommendations'][] = 'System optimization completed successfully';  $optimization_results['recommendations'][] = 'Schedule regular optimizations for optimal performance';  }  echo json_encode([  'success' => true,  'data' => $optimization_results  ]);  } catch(Exception $e) {  echo json_encode([  'success' => false,  'error' => 'System optimization failed: ' . $e->getMessage()  ]);
}
?>
